import heapq


class CycleError(Exception):
    pass


def order(deps):
    # Every node mentioned anywhere: keys and everything in their dep lists.
    nodes = set(deps)
    for ds in deps.values():
        nodes.update(ds)

    # Unmet dependencies per node (as sets so duplicates don't double-count).
    remaining = {n: set(deps.get(n, ())) for n in nodes}

    # Reverse edges: which nodes depend on each node.
    dependents = {n: set() for n in nodes}
    for n, ds in deps.items():
        for d in ds:
            dependents[d].add(n)

    # Nodes with no unmet dependencies, smallest picked first.
    ready = [n for n in nodes if not remaining[n]]
    heapq.heapify(ready)

    out = []
    while ready:
        # Pick the smallest currently ready node; readiness is re-evaluated
        # after every pick because new ready nodes enter the heap here.
        n = heapq.heappop(ready)
        out.append(n)
        for m in dependents[n]:
            remaining[m].discard(n)
            if not remaining[m]:
                heapq.heappush(ready, m)

    if len(out) != len(nodes):
        raise CycleError()
    return out

